  );
  --gradient-dusk: linear-gradient(
    -100deg,
    var(--dusk-900) 0%,
    var(--dusk-600) 48%,
    var(--dusk-800) 100%
  );
  --gradient-equinox: linear-gradient(
    -100deg,
    var(--dusk-400) 0%,
    var(--dusk-700) 40%,
    var(--aurora-950) 60%,
    var(--aurora-900) 100%
